package api

var sswCurriculumWoodIndustryCautionsEnglish = map[examSSWEnglishKey]string{
	{field: "ssw.caution", source: `Jangan menggabungkan bahan tanpa identitas dengan lot yang sudah diperiksa.`}:              `Do not combine unidentified material with a lot that has already been inspected.`,
	{field: "ssw.caution", source: `Jangan menetapkan kelas mutu sendiri di luar kriteria dan kewenangan.`}:                    `Do not assign a quality grade outside the criteria and your authority.`,
	{field: "ssw.caution", source: `Jangan mencampur catatan atau target kadar air dari jenis dan lot berbeda.`}:               `Do not mix records or moisture targets from different types and lots.`,
	{field: "ssw.caution", source: `Jangan melepas pelindung atau membersihkan mesin yang masih bergerak.`}:                    `Do not remove guards or clean a machine while it is moving.`,
	{field: "ssw.caution", source: `Jangan menebak satuan atau ukuran dari produk yang pernah dikerjakan.`}:                    `Do not guess units or dimensions based on a product handled previously.`,
	{field: "ssw.caution", source: `Jangan mengganti perekat atau urutan lapisan tanpa persetujuan proses.`}:                   `Do not change the adhesive or layer sequence without process approval.`,
	{field: "ssw.caution", source: `Jangan menggunakan alat ukur rusak atau mengubah catatan hasil pengukuran.`}:               `Do not use a damaged measuring tool or alter measurement records.`,
	{field: "ssw.caution", source: `Jangan menyamarkan cacat dengan menumpuknya di sisi tersembunyi.`}:                         `Do not conceal a defect by stacking it on the hidden side.`,
	{field: "ssw.caution", source: `Jangan mengganti label atau grade berdasarkan dugaan.`}:                                    `Do not replace a label or grade based on a guess.`,
	{field: "ssw.caution", source: `Jangan berdiri atau bekerja di bawah tumpukan yang tampak bergeser.`}:                      `Do not stand or work beneath a stack that appears to be shifting.`,
	{field: "ssw.caution", source: `Jangan mengubah label tujuan untuk menutup kekurangan pesanan.`}:                           `Do not change a destination label to conceal an order shortage.`,
	{field: "ssw.caution", source: `Jangan membersihkan bagian bergerak atau memperbaiki mesin tanpa isolasi dan kewenangan.`}: `Do not clean moving parts or repair a machine without isolation and authorization.`,
}

var sswCurriculumWoodIndustryStepsEnglish = map[examSSWEnglishKey]string{
	{field: "ssw.step", source: `Baca dokumen dan identitas kelompok kayu`}:                `Read the documents and wood-lot identification`,
	{field: "ssw.step", source: `Periksa jumlah serta kondisi yang terlihat`}:              `Check the quantity and visible condition`,
	{field: "ssw.step", source: `Catat selisih atau kerusakan aktual`}:                     `Record actual discrepancies or damage`,
	{field: "ssw.step", source: `Pisahkan bahan yang meragukan dan minta konfirmasi`}:      `Set questionable material aside and request confirmation`,
	{field: "ssw.step", source: `Baca spesifikasi produk dan contoh penerimaan`}:           `Read the product specifications and acceptance sample`,
	{field: "ssw.step", source: `Amati serat, retak, mata kayu, dan bentuk`}:               `Examine the grain, cracks, knots, and shape`,
	{field: "ssw.step", source: `Tandai atau pisahkan bagian yang tidak sesuai`}:           `Mark or separate nonconforming pieces`,
	{field: "ssw.step", source: `Laporkan keadaan yang memerlukan penilaian`}:              `Report conditions that require evaluation`,
	{field: "ssw.step", source: `Cocokkan identitas tumpukan dengan target pengeringan`}:   `Match the stack identity to the drying target`,
	{field: "ssw.step", source: `Periksa alat ukur dan posisi pengukuran yang ditetapkan`}: `Check the measuring tool and designated measurement points`,
	{field: "ssw.step", source: `Catat hasil kadar air dan waktu aktual`}:                  `Record the actual moisture reading and time`,
	{field: "ssw.step", source: `Simpan atau tahan tumpukan sesuai keputusan pemimpin`}:    `Store or hold the stack as directed by the lead`,
	{field: "ssw.step", source: `Baca instruksi operasi dan batas tugas`}:                  `Read the operating instructions and duty limits`,
	{field: "ssw.step", source: `Periksa pelindung, kontrol, dan area sekitar`}:            `Check guards, controls, and the surrounding area`,
	{field: "ssw.step", source: `Laporkan kondisi tidak normal sebelum menyalakan`}:        `Report abnormal conditions before starting the machine`,
	{field: "ssw.step", source: `Jalankan hanya setelah pemeriksaan dan izin selesai`}:     `Operate only after checks and authorization are complete`,
	{field: "ssw.step", source: `Cocokkan bahan, kode produk, dan lembar ukuran`}:          `Match the material and product code to the size sheet`,
	{field: "ssw.step", source: `Pastikan satuan serta arah kerja dipahami`}:               `Make sure the units and work direction are understood`,
	{field: "ssw.step", source: `Atur mesin hanya menurut instruksi yang disetujui`}:       `Set up the machine only according to approved instructions`,
	{field: "ssw.step", source: `Periksa sampel awal dan laporkan selisih`}:                `Inspect the first sample and report discrepancies`,
	{field: "ssw.step", source: `Baca jenis panel dan identitas setiap bahan`}:             `Read the panel type and the identity of each material`,
	{field: "ssw.step", source: `Cocokkan urutan serta arah lapisan dengan instruksi`}:     `Match the layer sequence and orientation to the instructions`,
	{field: "ssw.step", source: `Periksa kondisi bahan dan perekat yang ditetapkan`}:       `Check the material condition and specified adhesive`,
	{field: "ssw.step", source: `Jalankan atau serahkan proses sesuai batas tugas`}:        `Operate or hand over the process within your assigned duties`,
	{field: "ssw.step", source: `Baca toleransi dan titik ukur pada lembar mutu`}:          `Read the tolerances and measurement points on the quality sheet`,
	{field: "ssw.step", source: `Periksa alat ukur serta satuannya`}:                       `Check the measuring tool and its units`,
	{field: "ssw.step", source: `Ukur sampel dan catat hasil aktual`}:                      `Measure the sample and record the actual result`,
	{field: "ssw.step", source: `Tahan produk terkait dan laporkan hasil di luar batas`}:   `Hold the affected products and report results outside the limits`,
	{field: "ssw.step", source: `Bandingkan produk dengan sampel atau kriteria mutu`}:      `Compare the product with the sample or quality criteria`,
	{field: "ssw.step", source: `Periksa permukaan, tepi, dan ujung dengan aman`}:          `Safely inspect the surface, edges, and ends`,
	{field: "ssw.step", source: `Pisahkan produk yang tampak tidak sesuai`}:                `Separate products that appear nonconforming`,
	{field: "ssw.step", source: `Catat lokasi cacat dan laporkan`}:                         `Record the defect location and report it`,
	{field: "ssw.step", source: `Baca spesifikasi dan tanda kelompok produk`}:              `Read the product specifications and lot markings`,
	{field: "ssw.step", source: `Cocokkan label, jumlah, serta tujuan`}:                    `Check the labels, quantity, and destination`,
	{field: "ssw.step", source: `Tahan kelompok bila identitas atau grade meragukan`}:      `Hold the lot if its identity or grade is uncertain`,
	{field: "ssw.step", source: `Catat selisih dan minta pengesahan`}:                      `Record discrepancies and request approval`,
	{field: "ssw.step", source: `Periksa lantai dan penyangga tumpukan`}:                   `Check the floor and stack supports`,
	{field: "ssw.step", source: `Pastikan identitas serta arah susunan benar`}:             `Confirm the identity and stacking direction are correct`,
	{field: "ssw.step", source: `Susun hanya pada batas tinggi yang ditetapkan`}:           `Stack only up to the specified height limit`,
	{field: "ssw.step", source: `Jauhkan orang dan laporkan bundel tidak stabil`}:          `Keep people away and report unstable bundles`,
	{field: "ssw.step", source: `Baca pesanan dan identitas tujuan`}:                       `Read the order and destination identification`,
	{field: "ssw.step", source: `Hitung bundel serta cocokkan ukuran produk`}:              `Count the bundles and check product dimensions`,
	{field: "ssw.step", source: `Periksa ikatan dan label setelah dikemas`}:                `Check the ties and labels after packaging`,
	{field: "ssw.step", source: `Konfirmasi tujuan sebelum memuat`}:                        `Confirm the destination before loading`,
	{field: "ssw.step", source: `Baca daftar kebersihan dan perawatan rutin`}:              `Read the cleaning and routine-maintenance checklist`,
	{field: "ssw.step", source: `Bersihkan area dengan alat serta urutan yang disetujui`}:  `Clean the area using approved tools and sequence`,
	{field: "ssw.step", source: `Tandai dan laporkan kondisi mesin tidak normal`}:          `Mark and report abnormal machine conditions`,
	{field: "ssw.step", source: `Serahkan status mesin, lot, dan pekerjaan terbuka`}:       `Hand over machine and lot status and any outstanding work`,
}

var sswCurriculumWoodIndustryMeaningsEnglish = map[examSSWEnglishKey]string{
	{field: "ssw.meaning", source: `kayu`}:                                                                     `wood`,
	{field: "ssw.meaning", source: `lot atau kelompok produksi`}:                                               `lot or production batch`,
	{field: "ssw.meaning", source: `Kayu ini tidak memiliki tanda lot.`}:                                       `This wood has no lot marking.`,
	{field: "ssw.meaning", source: `Saya akan bertanya kepada penanggung jawab sebelum memindahkannya.`}:       `I will ask the person in charge before moving it.`,
	{field: "ssw.meaning", source: `pola serat kayu`}:                                                          `wood grain pattern`,
	{field: "ssw.meaning", source: `lingkaran tahun`}:                                                          `growth rings`,
	{field: "ssw.meaning", source: `mata kayu`}:                                                                `knot`,
	{field: "ssw.meaning", source: `retak`}:                                                                    `crack`,
	{field: "ssw.meaning", source: `Papan ini memiliki retak yang panjang.`}:                                   `This board has a long crack.`,
	{field: "ssw.meaning", source: `Saya minta petugas mutu memeriksanya.`}:                                    `I will ask quality-control staff to inspect it.`,
	{field: "ssw.meaning", source: `kadar air`}:                                                                `moisture content`,
	{field: "ssw.meaning", source: `penumpukan`}:                                                               `stacking`,
	{field: "ssw.meaning", source: `Saya akan mencatat kadar air lot ini.`}:                                    `I will record this lot's moisture content.`,
	{field: "ssw.meaning", source: `Hasilnya berbeda dari target. Saya akan melapor kepada penanggung jawab.`}: `The result differs from the target. I will report it to the person in charge.`,
	{field: "ssw.meaning", source: `Pelindung tidak bisa menutup. Saya menghentikan pengoperasian.`}:           `The guard will not close. I am stopping operation.`,
	{field: "ssw.meaning", source: `Kita lanjut setelah mesin diperiksa.`}:                                     `We will continue after the machine has been inspected.`,
	{field: "ssw.meaning", source: `penggergajian kayu`}:                                                       `wood sawing`,
	{field: "ssw.meaning", source: `ukuran`}:                                                                   `size or dimension`,
	{field: "ssw.meaning", source: `ketebalan`}:                                                                `thickness`,
	{field: "ssw.meaning", source: `Tanda ketebalannya berbeda.`}:                                              `The thickness marking is different.`,
	{field: "ssw.meaning", source: `Mohon pastikan instruksi sebelum memotong.`}:                               `Please confirm the instruction before cutting.`,
	{field: "ssw.meaning", source: `lembar venir`}:                                                             `veneer sheet`,
	{field: "ssw.meaning", source: `kayu lapis`}:                                                               `plywood`,
	{field: "ssw.meaning", source: `kayu laminasi`}:                                                            `laminated wood`,
	{field: "ssw.meaning", source: `perekat`}:                                                                  `adhesive`,
	{field: "ssw.meaning", source: `Mohon periksa arah lembar venir ini.`}:                                     `Please check the orientation of this veneer sheet.`,
	{field: "ssw.meaning", source: `Perekat digunakan sesuai instruksi.`}:                                      `Use the adhesive according to instructions.`,
	{field: "ssw.meaning", source: `toleransi`}:                                                                `tolerance`,
	{field: "ssw.meaning", source: `Hasil ukur berada di luar toleransi.`}:                                     `The measurement is outside the tolerance.`,
	{field: "ssw.meaning", source: `Saya menahan produk ini dan melapor kepada petugas.`}:                      `I am holding this product and reporting it to the staff member in charge.`,
	{field: "ssw.meaning", source: `tepi`}:                                                                     `edge`,
	{field: "ssw.meaning", source: `serpihan kayu`}:                                                            `wood splinter`,
	{field: "ssw.meaning", source: `Ada serpihan kayu di tepinya.`}:                                            `There is a wood splinter on the edge.`,
	{field: "ssw.meaning", source: `kelas atau grade`}:                                                         `grade`,
	{field: "ssw.meaning", source: `nomor produk`}:                                                             `product number`,
	{field: "ssw.meaning", source: `Label ini tidak dapat dibaca.`}:                                            `This label is unreadable.`,
	{field: "ssw.meaning", source: `Saya akan memeriksa nomor produk sebelum pengiriman.`}:                     `I will check the product number before dispatch.`,
	{field: "ssw.meaning", source: `muatan roboh`}:                                                             `stack collapse`,
	{field: "ssw.meaning", source: `stabil`}:                                                                   `stable`,
	{field: "ssw.meaning", source: `Bundel ini miring. Jangan mendekat.`}:                                      `This bundle is leaning. Do not come close.`,
	{field: "ssw.meaning", source: `pengikatan`}:                                                               `tying or strapping`,
	{field: "ssw.meaning", source: `tujuan pengiriman`}:                                                        `shipping destination`,
	{field: "ssw.meaning", source: `Tanda tujuan pengiriman berbeda.`}:                                         `The shipping-destination marking is different.`,
	{field: "ssw.meaning", source: `Saya akan mencocokkan pesanan sebelum memuat.`}:                            `I will check the order before loading.`,
	{field: "ssw.meaning", source: `Ada kebocoran di dekat mesin.`}:                                            `There is a leak near the machine.`,
	{field: "ssw.meaning", source: `Saya mencatat lokasi dan waktu, lalu memberi tahu penanggung jawab.`}:      `I will record the location and time, then notify the person in charge.`,
}
